// Sign-in, first-run setup and permissions — generated by `mcn build --target flutter`.
import 'package:flutter/material.dart';

import 'api.dart';

enum AuthStatus { loading, setup, signedOut, ready }

class AuthState extends ChangeNotifier {
  AuthState({required this.enabled});

  /// False when the MCN app has no `auth` block: everything is allowed.
  final bool enabled;

  AuthStatus status = AuthStatus.loading;
  Map<String, dynamic>? user;
  List<String> permissions = const [];

  String? get role => user?['role'] as String?;

  Future<void> init() async {
    api.onUnauthorized = () {
      logout();
    };
    await api.loadToken();
    if (!enabled) {
      status = AuthStatus.ready;
      notifyListeners();
      return;
    }
    if (api.token != null) {
      try {
        _signedIn(await api.get('/me'));
        return;
      } catch (_) {
        await api.setToken(null);
      }
    }
    try {
      final s = await api.get('/auth_status');
      status = (s is Map && s['needs_setup'] == true) ? AuthStatus.setup : AuthStatus.signedOut;
    } catch (_) {
      status = AuthStatus.signedOut;
    }
    notifyListeners();
  }

  void _signedIn(dynamic data) {
    user = Map<String, dynamic>.from(data['user'] as Map);
    permissions = List<String>.from((data['permissions'] as List?) ?? const []);
    status = AuthStatus.ready;
    notifyListeners();
  }

  Future<void> login(String email, String password) async {
    final d = await api.post('/login', {'email': email, 'password': password});
    await api.setToken(d['token'] as String?);
    _signedIn(d);
  }

  Future<void> setup(String name, String email, String password) async {
    final d = await api.post('/setup', {'name': name, 'email': email, 'password': password});
    await api.setToken(d['token'] as String?);
    _signedIn(d);
  }

  Future<void> logout() async {
    await api.setToken(null);
    user = null;
    permissions = const [];
    status = AuthStatus.signedOut;
    notifyListeners();
  }

  /// can('/create_lead')
  bool can(String endpoint) =>
      !enabled || permissions.contains(endpoint.startsWith('/') ? endpoint.substring(1) : endpoint);

  bool hasRole(List<String> roles) =>
      !enabled || (user != null && (roles.isEmpty || roles.contains(role)));
}

/// Makes the AuthState available to every screen: `AuthScope.of(context)`.
class AuthScope extends InheritedNotifier<AuthState> {
  const AuthScope({super.key, required AuthState auth, required super.child})
      : super(notifier: auth);

  static AuthState of(BuildContext context) =>
      context.dependOnInheritedWidgetOfExactType<AuthScope>()!.notifier!;
}

/// Shows the sign-in (or first-run setup) screen until someone is signed in.
class AuthGate extends StatelessWidget {
  const AuthGate({super.key, required this.title, required this.child});

  final String title;
  final Widget child;

  @override
  Widget build(BuildContext context) {
    final auth = AuthScope.of(context);
    switch (auth.status) {
      case AuthStatus.loading:
        return const Scaffold(body: Center(child: CircularProgressIndicator()));
      case AuthStatus.setup:
        return SignInScreen(title: title, setup: true);
      case AuthStatus.signedOut:
        return SignInScreen(title: title, setup: false);
      case AuthStatus.ready:
        return child;
    }
  }
}

class SignInScreen extends StatefulWidget {
  const SignInScreen({super.key, required this.title, required this.setup});

  final String title;
  final bool setup;

  @override
  State<SignInScreen> createState() => _SignInScreenState();
}

class _SignInScreenState extends State<SignInScreen> {
  final _name = TextEditingController();
  final _email = TextEditingController();
  final _password = TextEditingController();
  String _error = '';
  Map<String, String> _fieldErrors = const {};
  bool _busy = false;

  @override
  void dispose() {
    _name.dispose();
    _email.dispose();
    _password.dispose();
    super.dispose();
  }

  Future<void> _submit() async {
    final auth = AuthScope.of(context);
    setState(() {
      _busy = true;
      _error = '';
      _fieldErrors = const {};
    });
    try {
      if (widget.setup) {
        await auth.setup(_name.text, _email.text.trim(), _password.text);
      } else {
        await auth.login(_email.text.trim(), _password.text);
      }
    } on ApiError catch (e) {
      setState(() {
        _error = e.message;
        _fieldErrors = e.fieldErrors;
      });
    } catch (e) {
      setState(() => _error = 'Could not reach the server ($apiBase)');
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    return Scaffold(
      body: SafeArea(
        child: Center(
          child: SingleChildScrollView(
            padding: const EdgeInsets.all(24),
            child: ConstrainedBox(
              constraints: const BoxConstraints(maxWidth: 380),
              child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
                Icon(Icons.lock_outline, size: 40, color: theme.colorScheme.primary),
                const SizedBox(height: 16),
                Text(widget.setup ? 'Create the admin account' : 'Sign in to ${widget.title}',
                    textAlign: TextAlign.center, style: theme.textTheme.headlineSmall),
                const SizedBox(height: 8),
                Text(
                    widget.setup
                        ? 'No users yet. The first account becomes the administrator.'
                        : 'Enter your email and password to continue.',
                    textAlign: TextAlign.center,
                    style: theme.textTheme.bodyMedium),
                const SizedBox(height: 24),
                if (widget.setup) ...[
                  TextField(
                      controller: _name,
                      decoration: InputDecoration(
                          labelText: 'Name', errorText: _fieldErrors['name'],
                          border: const OutlineInputBorder())),
                  const SizedBox(height: 12),
                ],
                TextField(
                    controller: _email,
                    keyboardType: TextInputType.emailAddress,
                    autofillHints: const [AutofillHints.email],
                    decoration: InputDecoration(
                        labelText: 'Email', errorText: _fieldErrors['email'],
                        border: const OutlineInputBorder())),
                const SizedBox(height: 12),
                TextField(
                    controller: _password,
                    obscureText: true,
                    onSubmitted: (_) => _submit(),
                    decoration: InputDecoration(
                        labelText: 'Password', errorText: _fieldErrors['password'],
                        border: const OutlineInputBorder())),
                if (_error.isNotEmpty && _fieldErrors.isEmpty) ...[
                  const SizedBox(height: 12),
                  Text(_error, style: TextStyle(color: theme.colorScheme.error)),
                ],
                const SizedBox(height: 20),
                FilledButton(
                  onPressed: _busy ? null : _submit,
                  child: _busy
                      ? const SizedBox(height: 18, width: 18, child: CircularProgressIndicator(strokeWidth: 2))
                      : Text(widget.setup ? 'Create account' : 'Sign in'),
                ),
              ]),
            ),
          ),
        ),
      ),
    );
  }
}
